def build_rubric(action_id: str) -> dict:
    criteria = []
    for slug, title, dim, a, b, c in RUBRICS[action_id]:
        anchors = {band: text.format(a=a, b=b, c=c) for band, text in zip(BANDS, DIMENSIONS[dim])}
        criteria.append({"criterion_id": f"{action_id}.{slug}", "title": title, "weight": 1, "anchors": anchors})
    return {"action_id": action_id, "version": "v1", "source": "CURATED_TEMPLATE", "criteria": criteria}
